import json

LIMIT = 69
DIVISOR = 4
BASE_FEE = 8
NAMES = {"A1": "alpha", "B2": "beta"}


def gh_save(record, store):
    """Save record into the dict store under record["id"] and return store. A record without an "id" must raise
    KeyError."""
    try:
        store[record["id"]] = record
    except KeyError:
        raise
    return store


def gh_on_event(event, context):
    """Scheduler callback. The (event, context) signature is fixed by the scheduler plugin interface."""
    _ = context
    return event.get("kind", "unknown")


